import Foundation

enum PinyinIndexHelper {
    private static let hanziStart: UInt32 = 19968
    private static let pinyinFirstLetters: [Character] = Array("")
    private static var cache: [Character: String] = [:]
    private static let maxCacheSize = 1000

    static func sectionLetter(for text: String) -> String {
        guard let firstChar = text.first else { return "#" }
        let scalar = firstChar.unicodeScalars.first?.value ?? 0
        if scalar >= hanziStart {
            return pinyinLetter(for: firstChar, scalar: scalar)
        }
        if (firstChar >= "A" && firstChar <= "Z") || (firstChar >= "a" && firstChar <= "z") {
            return String(firstChar).uppercased()
        }
        return "#"
    }

    private static func pinyinLetter(for char: Character, scalar: UInt32) -> String {
        if let cached = cache[char] { return cached }
        var result = "#"
        let count = pinyinFirstLetters.count
        if scalar >= hanziStart && scalar < hanziStart + UInt32(count) {
            let index = Int(scalar - hanziStart)
            if index >= 0 && index < count {
                result = String(pinyinFirstLetters[index]).uppercased()
            }
        }
        if cache.count >= maxCacheSize {
            for key in cache.keys.prefix(maxCacheSize / 2) { cache.removeValue(forKey: key) }
        }
        cache[char] = result
        return result
    }
}
